\begin{figure}[t]
    \centering
    \includegraphics[width=0.45\textwidth]{line.pdf}
    \caption{Left: single-cell SRF cavity equipped with frequency tuner. Right: schematic of the microwave electronics for DPDM searches. The VNA measures the net amplification factor $G_{\rm net}$ of the amplifier circuit consisting of an isolator, a HEMT amplifier, and two room-temperature amplifiers. The noise source and the spectrum analyzer calibrate the resonant frequencies $f_0^i$. The time-domain signals from the SRF, with sequential amplification, are finally recorded by the spectrum analyzer.
     }
    \label{SRFmodes}
